  { id: 'HG-10236', placed: '9 Oct 2026', items: 'Oak chopping board, olive-wood salad servers', total: '£54.00', status: 'delivered', detail: 'Delivered 12 Oct at 11:20, signed for and left with the resident.' },
  { id: 'HG-10237', placed: '2 Oct 2026', items: 'Electric milk frother', total: '£44.00', status: 'return received', detail: 'Return reached the warehouse 18 Oct; refund of £44.00 issued 19 Oct to the original card (3-5 working days to show).' },
  { id: 'HG-10238', placed: '18 Oct 2026', items: 'Copper kettle 1.7 L', total: '£69.00', status: 'cancelled', detail: 'Cancelled by the customer 25 minutes after ordering; payment voided, never charged.' },
];
const PRODUCTS = [
  { sku: 'CK-24', name: 'Cast-iron casserole 24 cm', category: 'cookware', price: '£64.00', stock: 12 },
  { sku: 'CK-17', name: 'Copper kettle 1.7 L', category: 'cookware', price: '£69.00', stock: 0 },
  { sku: 'TW-04', name: 'Stoneware mug set of 4', category: 'tableware', price: '£32.00', stock: 40 },
  { sku: 'TW-12', name: 'Linen napkins, set of 6', category: 'textiles', price: '£24.00', stock: 18 },
  { sku: 'KT-OB', name: 'Oak chopping board', category: 'kitchen tools', price: '£36.00', stock: 9 },
  { sku: 'KT-OS', name: 'Olive-wood salad servers', category: 'kitchen tools', price: '£18.00', stock: 25 },
  { sku: 'EL-MF', name: 'Electric milk frother', category: 'electricals', price: '£44.00', stock: 6 },
  { sku: 'TX-TT', name: 'Linen tea towels, pair', category: 'textiles', price: '£14.00', stock: 30 },
  { sku: 'GC-ANY', name: 'Digital gift card (£10-£200)', category: 'gift cards', price: 'from £10', stock: 999 },
];
const A = (() => { if (query && typeof query === 'object') return query; try { return JSON.parse(query); } catch (e) { return { text: String(query || '') }; } })();

// get_order_status: look up one sample order (names and emails are never returned)
const raw = String(A.order_id || A.text || '').toUpperCase();
const m = raw.match(/(\d{5})/);
const o = m && ORDERS.find((x) => x.id === 'HG-' + m[1]);
